ts#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/962599627/agent-development-constraints/issues\"\n  },\n  \"scripts\": {\n    \"test\": \"node tests/plugin.spec.mjs\"\n  }\n}\n"
